    grid[row][col] = "#"
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = row + dr, col + dc
        if 0 <= nr < r and 0 <= nc < c and grid[nr][nc] != "#":
            explore(grid, r, c, nr, nc, nxt, found)
    grid[row][col] = ch

